/** Pick exemplars for a slide kind: the kind-specific one first, then a complementary one. */
export function exemplarsFor(kind: string): Exemplar[] {
  const order: Record<string, string[]> = { numbers: ['ir-13-market-targets', 'gochang-05-numbers'], chart: ['ir-04-market-slider', 'p800-15-wafer'], demo: ['ir-06-showcase', 'ir-08-translate'], process: ['p800-12-process', 'gochang-21-prompt-formula'], compare: ['gochang-12-chat-to-agent', 'gochang-10-three-companies'], concept: ['ir-10-smartglass', 'gochang-12-chat-to-agent'], product: ['p800-23-hbm', 'ir-10-smartglass'], story: ['ir-13-market-targets', 'ir-06-showcase'], list: ['ir-13-market-targets', 'gochang-10-three-companies'], cover: ['ir-01-cover', 'gochang-01-cover'], section: ['gochang-07-section', 'gochang-01-cover'], closing: ['ir-20-closing', 'gochang-60-closing'], agenda: ['gochang-01-cover', 'gochang-21-prompt-formula'] };
  const ids = order[kind] || order.story;
  return ids.map(id => EXEMPLARS[id]).filter(Boolean);
}
